window.HOEREN_TESTS[79] = {"id":"im-schuhgeschaeft","name":"Im Schuhgeschäft","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Heute ist großer Schlussverkauf im Schuhgeschäft. Alle Winterstiefel sind 50 Prozent günstiger. Sommerschuhe sind aber nicht reduziert, die sind neu, und nicht alle Schuhe sind im Angebot. Die Aktion gilt nur bis Samstag. Greifen Sie zu, solange Ihre Größe noch da ist. Wir freuen uns auf Sie!","gender":"f","q":"Welche Schuhe sind im Angebot?","opts":["Sommerschuhe.","Winterstiefel.","Alle Schuhe."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Ich brauche neue Laufschuhe für den Marathon, keine Wanderschuhe und keine Sandalen. Meine alten tun nach 10 Kilometern weh. Du läufst doch auch. Welche Marke empfiehlst du? Im Geschäft kann man auf einem Laufband testen, wusstest du das? Kommst du mit? Ruf zurück, danke dir!","gender":"m","q":"Was für Schuhe braucht Markus?","opts":["Laufschuhe.","Wanderschuhe.","Sandalen."],"correct":0},{"transcript":"Achtung Kunden: Wir tauschen Schuhe gern um, aber nur ungetragene Schuhe mit Kassenbon. Getragene Schuhe können wir leider nicht zurücknehmen, und nicht alle Schuhe darf man umtauschen. Bei einem Defekt innerhalb von sechs Monaten reparieren wir kostenlos oder tauschen um. Bewahren Sie also den Bon gut auf. Vielen Dank!","gender":"m","q":"Welche Schuhe kann man umtauschen?","opts":["Ungetragene Schuhe mit Bon.","Getragene Schuhe.","Alle Schuhe."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hey, ich habe so schöne rote Schuhe gefunden, aber sie hatten nur noch eine Nummer zu klein, nicht zu groß und nicht kaputt. Ich habe sie trotzdem genommen, vielleicht werden sie weiter. War das dumm? Sie drücken ein bisschen. Soll ich sie umtauschen? Sag mir deine Meinung, bis bald!","gender":"f","q":"Was ist das Problem mit Annas Schuhen?","opts":["Sie sind zu groß.","Sie sind kaputt.","Sie sind zu klein."],"correct":2},{"transcript":"Liebe Eltern: In unserem Geschäft messen wir Kinderfüße kostenlos und genau. Es gibt keine kostenlosen Schuhe und keinen Spielplatz, aber das Füßemessen ist frei. Kinder wachsen schnell, falsche Schuhe schaden den Füßen. Wir beraten Sie gern, welche Größe und welche Form passt. Kommen Sie am besten nachmittags. Wir helfen Ihnen gern!","gender":"f","q":"Was bietet das Geschäft für Kinder an?","opts":["Kostenlose Schuhe.","Kostenloses Füßemessen.","Einen Spielplatz."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft welche Schuhe? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Laden ist heute voll. Suchen wir für jeden das richtige Paar?"},{"speaker":"Lisa","gender":"f","text":"Ich habe den Zettel von der Familie. Die Nummern stehen hier auf dem Blatt."},{"speaker":"Lukas","gender":"m","text":"Ich nehme Laufschuhe. Ich laufe weit und die alten sind kaputt."},{"speaker":"Lisa","gender":"f","text":"Die leichten hängen links. Kauft jemand bunte Sneaker für die Schule?"},{"speaker":"Lukas","gender":"m","text":"Sneaker kauft bei uns keiner. Jeder hat schon ein Paar."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe High Heels für die Feier am Samstag."},{"speaker":"Lukas","gender":"m","text":"Die roten passen zu deinem Kleid. Was braucht Tom für die Berge?"},{"speaker":"Lisa","gender":"f","text":"Tom kauft Wanderschuhe. Am Wochenende geht er mit Freunden auf einen hohen Weg."},{"speaker":"Lukas","gender":"m","text":"Braucht jemand Gummistiefel für den Garten? Der Boden ist diese Woche nass."},{"speaker":"Lisa","gender":"f","text":"Gummistiefel braucht auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara schreibt, dass sie noch etwas für den Sommer braucht."},{"speaker":"Lisa","gender":"f","text":"Sara kauft Sandalen. Im Juli läuft sie damit fast jeden Tag am Wasser."},{"speaker":"Lukas","gender":"m","text":"Tim arbeitet jeden Tag draußen auf dem Platz."},{"speaker":"Lisa","gender":"f","text":"Tim kauft Arbeitsschuhe. Ohne sie darf er die Tür zur Halle nicht öffnen."},{"speaker":"Lukas","gender":"m","text":"Das ist dort die Regel."},{"speaker":"Lisa","gender":"f","text":"Ich nehme unsere Paare mit zur Kasse."}],"options":[{"letter":"a","text":"Sandalen"},{"letter":"b","text":"Wanderschuhe"},{"letter":"c","text":"Hausschuhe"},{"letter":"d","text":"Sneaker"},{"letter":"e","text":"High Heels"},{"letter":"f","text":"Laufschuhe"},{"letter":"g","text":"Winterstiefel"},{"letter":"h","text":"Arbeitsschuhe"},{"letter":"i","text":"Gummistiefel"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, haben Sie diese Schuhe in Größe 39? Nicht 38 und nicht 40, bitte 39."},{"speaker":"Verkäufer","gender":"m","text":"Einen Moment, ich schaue im Lager nach Größe 39, für Sie."},{"speaker":"Kundin","gender":"f","text":"Danke, Größe 39 ist super."},{"speaker":"Verkäufer","gender":"m","text":"Leider nur noch 38 und 40, Größe 39 ist heute aus."},{"speaker":"Kundin","gender":"f","text":"Schade, ich brauche 39. 38 und 40 passen nicht. Danke trotzdem. Tschüss!"},{"speaker":"Verkäufer","gender":"m","text":"Soll ich 39 bestellen? Dauert drei Tage."}],"q":"Welche Größe sucht die Kundin?","opts":["38.","39.","40."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, diese Schuhe drücken vorne. Sie sind nicht zu groß, und die Farbe gefällt mir."},{"speaker":"Verkäuferin","gender":"f","text":"Soll ich eine Nummer größer holen? Zu groß sind sie also nicht, und die Farbe ist okay."},{"speaker":"Mann","gender":"m","text":"Ja, bitte eine Nummer größer, weil sie drücken."},{"speaker":"Verkäuferin","gender":"f","text":"Hier, probieren Sie die mal. Die Farbe ist gleich, nur eine Nummer größer."},{"speaker":"Mann","gender":"m","text":"Danke, die dürfen nicht drücken. Die Farbe behalte ich."}],"q":"Was ist das Problem?","opts":["Die Schuhe drücken.","Die Schuhe sind zu groß.","Die Farbe gefällt nicht."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, was kosten diese Stiefel? 120 Euro oder 100 Euro?"},{"speaker":"Verkäufer","gender":"m","text":"Normal 120 Euro, heute 80 Euro, nicht 100 Euro."},{"speaker":"Kunde","gender":"m","text":"Sind die aus echtem Leder, die Stiefel für 80 Euro?"},{"speaker":"Verkäufer","gender":"m","text":"Ja, echtes Leder. Heute 80, sonst 120, nicht 100."},{"speaker":"Kunde","gender":"m","text":"Dann nehme ich sie heute für 80 Euro. Danke, tschüss!"},{"speaker":"Verkäufer","gender":"m","text":"Gute Wahl! Soll ich sie als Geschenk einpacken?"}],"q":"Was kosten die Stiefel heute?","opts":["120 Euro.","100 Euro.","80 Euro."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, mein Absatz ist abgebrochen. Die Sohle und der Riemen sind okay."},{"speaker":"Schuhmacher","gender":"m","text":"Das kann ich reparieren. Sohle und Riemen muss ich nicht machen, nur den Absatz."},{"speaker":"Frau","gender":"f","text":"Bis wann ist der Absatz fertig?"},{"speaker":"Schuhmacher","gender":"m","text":"Bis morgen Mittag. Sohle und Riemen bleiben, wie sie sind."},{"speaker":"Frau","gender":"f","text":"Gut, dann der Absatz bis morgen Mittag. Danke schön."}],"q":"Was ist kaputt?","opts":["Die Sohle.","Der Riemen.","Der Absatz."],"correct":2},{"lines":[{"speaker":"Mutter","gender":"f","text":"Guten Tag, welche Größe hat mein Sohn jetzt? Noch 29 oder schon 33?"},{"speaker":"Verkäuferin","gender":"f","text":"Ich messe mal. Größe 31, nicht 29 und nicht 33."},{"speaker":"Mutter","gender":"f","text":"Schon 31? Letztens war es 29."},{"speaker":"Verkäuferin","gender":"f","text":"Kinder wachsen eben schnell. Jetzt 31, 33 kommt später einmal."},{"speaker":"Mutter","gender":"f","text":"Verstehe, Größe 31. Dann nehme ich 31. Danke, tschüss!"},{"speaker":"Verkäuferin","gender":"f","text":"Probieren wir sie gleich an? Die Kasse ist dort drüben."}],"q":"Welche Größe hat der Sohn jetzt?","opts":["29.","31.","33."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Bauer, einer Schuhverkäuferin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Bauer, Sie verkaufen seit 25 Jahren Schuhe. Was ist der häufigste Fehler beim Schuhkauf?"},{"speaker":"Bauer","gender":"f","text":"Die Leute kaufen zu kleine Schuhe, weil ihnen das Modell gefällt. Sie sagen, die werden schon weiter. Meistens stimmt das nicht. Ein zu enger Schuh tut weh und schadet dem Fuß. Lieber das passende Modell in der richtigen Größe nehmen, auch wenn es weniger schick ist."},{"speaker":"Reporter","gender":"m","text":"Wann soll man Schuhe am besten kaufen?"},{"speaker":"Bauer","gender":"f","text":"Am Nachmittag oder Abend. Das überrascht viele. Aber die Füße werden im Laufe des Tages größer, sie schwellen leicht an. Wer morgens Schuhe kauft, hat abends oft zu enge. Probieren Sie immer beide Schuhe an und laufen Sie ein paar Schritte im Laden."},{"speaker":"Reporter","gender":"m","text":"Sind teure Schuhe besser als günstige?"},{"speaker":"Bauer","gender":"f","text":"Nicht immer, aber oft. Gute Schuhe halten länger und sind gesünder für die Füße. Bei Schuhen, die man jeden Tag trägt, lohnt sich Qualität. Für ein Fest, das man einmal besucht, reicht auch ein günstiges Paar. Es kommt darauf an, wofür man sie braucht."},{"speaker":"Reporter","gender":"m","text":"Wie pflegt man Schuhe richtig?"},{"speaker":"Bauer","gender":"f","text":"Lederschuhe regelmäßig eincremen, das hält sie weich und schön. Nach dem Regen nicht auf die Heizung stellen, sondern langsam trocknen lassen, sonst werden sie hart. Und am besten mehrere Paare im Wechsel tragen. Dann kann jeder Schuh zwischendurch trocknen und hält viel länger."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie beim Kauf von Kinderschuhen?"},{"speaker":"Bauer","gender":"f","text":"Immer genau messen lassen, denn Kinder spüren oft nicht, wenn ein Schuh zu klein ist. Und nicht die Schuhe der größeren Geschwister vererben, jeder Fuß ist anders. Lieber etwas Platz lassen zum Wachsen, aber nicht zu viel. Gute Kinderschuhe sind eine wichtige Investition in gesunde Füße."}],"items":[{"q":"Viele Leute kaufen zu kleine Schuhe, weil das Modell gefällt.","correct":"ja"},{"q":"Frau Bauer empfiehlt, Schuhe am besten morgens zu kaufen.","correct":"nein"},{"q":"Sie sagt, bei täglich getragenen Schuhen lohnt sich Qualität.","correct":"ja"},{"q":"Nasse Lederschuhe soll man auf die Heizung stellen.","correct":"nein"},{"q":"Bei Kinderschuhen rät sie, immer genau messen zu lassen.","correct":"ja"}]}]};
